WITH cleaned AS (SELECT *, LAST_DAY(hire_date) AS hire_date_month_end FROM employees WHERE is_remote) SELECT id, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, CUME_DIST() OVER (PARTITION BY job_title, manager_id ORDER BY salary) AS salary_cume_dist, AVG(salary) OVER (PARTITION BY manager_id ORDER BY hire_date, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS salary_avg_3_prior FROM cleaned WHERE level IS NULL
